export interface FlavorProfile {
  bitter: number;
  sweet: number;
  sour: number;
  spicy: number;
  strong: number;
}

export interface Prebatch {
  name: string;
  ingredients: string[];
  steps: string[];
}

export interface Recipe {
  name: string;
  region: string;
  author: string;
  bar: string;
  difficulty: 'easy' | 'medium' | 'hard';
  category: string;
  barDescription: string;
  barCity: string;
  tags: string[];
  intro: string;
  /** Фото коктейля на странице рецепта → папка public/images/recipes/ */
  image: string;
  /** Превью для карточек в коллекции и подборках → папка public/images/cards/ */
  cardImage?: string;
  method: string;
  glass: string;
  garnish: string;
  ice: string;
  prebatch: string | Prebatch | Prebatch[];
  flavorProfile: FlavorProfile;
  ingredients: string[];
  steps: string[];
  /** Ссылка на Instagram автора (URL или @handle). Для кнопки на карточке. */
  authorInstagram?: string;
  /** Ссылка на Telegram автора (URL или @handle). Для кнопки на карточке. */
  authorTg?: string;
  /** Фото автора → папка public/images/authors/ */
  authorImage?: string;
  /** Ссылка на бар (сайт, Instagram и т.д.). Для кнопки на карточке. */
  barLink?: string;
  /** Развёрнутое описание / сторителлинг на странице рецепта */
  story?: string;
}

export interface RecipeEntry {
  id: string;
  city: string;
  lat: number;
  lng: number;
  recipe: Recipe;
}

