      story:
        'Santi Negroni — это ода величию и богатой истории Италии. В основе коктейля лежит идея ритуала: двенадцать ингредиентов символизируют двенадцать святых, чьи образы охраняют культурное наследие страны.\n\nЭто не просто коктейль, а сложная многогранная композиция, объединяющая традиции разных регионов Италии. Каждый глоток раскрывает новый слой: нежность клубники, оттенки трюфеля, минеральность, аромат грейпфрута, пышность вермутов и глубокую, благородную горечь.\n\nДжины формируют ароматическую структуру напитка: от классической можжевеловой базы до клубничных, минеральных и пряных оттенков. Вермуты добавляют винную глубину, сладость, травянистость и объем. Campari, Martini Bitter и Fernet-Branca удерживают коктейль в классической горькой логике Negroni, но делают вкус более многослойным и торжественным.\n\nСусальное золото на самом дне бокала превращает подачу в символический жест. Оно подчёркивает идею святости, роскоши и культурного наследия, ради которого создан Santi Negroni.\n\nЭто коктейль, который пьётся как церемония: медленно, внимательно, через раскрытие аромата, текстуры, горечи и долгого послевкусия.',
