      story:
        'Coco Negroni — коктейль, с которого началась первая коктейльная карта бара Ichi by Relab.\n\nСо временем напиток несколько раз менялся, затем на какое-то время исчез из меню. Но у хороших коктейлей есть своя память: гости всё чаще просили вернуть тот самый Coco Negroni. И вот он снова в карте — и снова бьёт рекорды популярности.\n\nВ основе напитка — узнаваемая логика Negroni, но в более мягком, тропическом и травяном прочтении. Мятная водка даёт чистую свежесть и прохладный аромат. Cynar отвечает за травяную горечь и глубину. Красный вермут сохраняет винную сладость и пряность, какао-ликёр добавляет тёплый десертный оттенок, а кокосовая вода делает вкус мягче, легче и округлее.\n\nВаниль работает фоном, связывая кокос, какао и вермут в цельную композицию. А тёртый мускатный орех в гарнире добавляет пряный аромат и завершает профиль напитка.\n\nCoco Negroni — это возвращение барной классики конкретного места: коктейль, который гости запомнили, попросили вернуть и снова сделали популярным.',
