      intro:
        '«Дух Экстаза» — вишнёво-косточковая вариация на Negroni, вдохновлённая эстетикой Rolls-Royce и символом Spirit of Ecstasy. В коктейле джин, портвейн, Doragrossa Bitter, херес Fino, вишнёвый ликёр, амаретто и cherry-сироп соединяются в терпкий, сладко-горький профиль с миндально-косточковым акцентом.',
      story:
        'Автомобильная промышленность XX века удивляла разнообразием форм и стремлением к дизайнерскому идеалу. Одним из самых ярких символов этой эпохи стал Rolls-Royce — легендарная марка, известная вниманием к деталям, ремесленной точностью и особым отношением к форме.\n\nДаже небольшой элемент на капоте автомобиля — фигурка Spirit of Ecstasy, или «Дух Экстаза», — воспринимается как отдельный символ: не просто декоративная деталь, а знак статуса, движения и стремления к совершенству.\n\nВдохновившись этой идеей, автор воссоздал в коктейле дух кропотливого труда и точности, доведённой до блеска. Центральный вкусовой образ — черешневая косточка: терпкая, миндальная, чуть горькая и благородно сухая.\n\nВ этой версии итальянской классики профиль Negroni соединяется с вишнёвой глубиной, портвейном, хересом Fino, амаретто и ароматическими биттерами. Gatsby\'s Dry Gin даёт структуру, Doragrossa Bitter удерживает горькую аперитивную линию, портвейн добавляет винную плотность, Luxardo Cherry Sangue Morlacco раскрывает тёмную вишню, а Amaretto усиливает косточковый миндальный оттенок.\n\n«Дух Экстаза» — это коктейль о внимании к деталям. О том, как образ автомобильной роскоши, ручной работы и дизайнерского совершенства превращается в терпкий, вишнёвый и сладко-горький Negroni-твист.',
