      intro:
        'Manryu — лиричная вариация на Negroni, вдохновлённая историей японской гейши Манрю. В коктейле саке, джин Gintl на ку тсао, сливовый соджу, Campari, Vermouth Bianco и сливовый ликёр складываются в мягкий, горько-сладкий профиль с деликатной фруктовостью и лёгкой цитрусовой свежестью.',
      story:
        'В начале XX века Токио был городом перемен: старые традиции уступали место новому времени, а улицы наполнялись шёпотом шёлковых кимоно и светом электрических фонарей.\n\nВ это время жила гейша по имени Манрю — одна из самых искусных и прекрасных. Её танцы пленяли, голос чаровал, а искусство казалось безупречным. Но в августе 1910 года судьба резко изменила её жизнь. В Хаконе, где Манрю оказалась случайно, случилось наводнение. Ослабленная болезнью, она не могла спастись сама. Её спас студент юридического факультета Ёитиро Цунэкава — молодой, сильный и полный света.\n\nЧерез год их пути снова пересеклись. Между ними вспыхнула любовь, и Манрю оставила всё — сцену, славу, прежнюю жизнь — чтобы быть рядом с ним. Она выбрала не блеск, а тепло, не признание, а чувство. Но судьба не оказалась милостивой: через четыре года Ёитиро умер, и вместе с ним рухнул её мир. Манрю больше не вернулась к искусству гейши, но не пожалела о своём выборе.\n\nКоктейль Manryu — это не просто напиток, а история о выборе, который однажды встаёт перед каждым человеком. О любви, которая может быть жестокой, но именно она делает жизнь ослепительно яркой, даже если длится недолго.\n\nВо вкусе коктейля переплетаются нежность, боль и красота. Саке и сливовый соджу создают мягкую, текучую основу. Campari даёт горькую эмоцию утраты. Vermouth Bianco и сливовый ликёр добавляют деликатную сладость воспоминаний. Джин с инфьюзом на ку тсао добавляет тонкость и ароматическую глубину. Грейпфрут в гарнире завершает напиток лёгкой свежей горечью.\n\nManryu — это коктейль, который стоит пить медленно. Как историю, которую хочется дослушать до конца.',
