      story:
        'AGONY CHARM — это коктейль, в котором идея Negroni переосмысляется через метафору противоположностей.\n\nНазвание «Очарование агонии» выражает саму суть напитка. Если классический Negroni можно отнести к более «мужским» коктейлям — прямым, горьким и жёстким, то здесь появляется его более феминная версия: свежая, питкая, тонкая и обольстительная, но при этом не лишённая силы.\n\nОчарование здесь становится символом женской природы, а агония — в исходном греческом значении борьбы — мужской прерогативой. На этой дихотомии выстроен весь баланс вкуса и настроения: коктейль одновременно свежий и крепкий, мягкий и терпкий, деликатный и насыщенный.\n\nЗемляничный джин придаёт напитку ягодную мягкость и ароматическую привлекательность. Ржаной самогон добавляет русский характер и создаёт аллюзию к предку джина — женеверу. Fernet приносит горечь и травяную глубину. Кардиал пипали-вишня-ваниль связывает вкус в более округлую и сложную композицию, берёзовый сок добавляет лёгкость и природную чистоту, а розовая вода завершает профиль тонким цветочным штрихом.\n\nРозовое пищевое серебро и волнообразные печати на льду усиливают визуальный образ: это уже не просто коктейль, а украшение, жест и настроение.\n\nAGONY CHARM — это Negroni, в котором борьба и очарование существуют в одном бокале.',
