      story:
        '«Барокко» создан как вкусовое воплощение архитектурного стиля, который ассоциируется с торжественностью, декоративным богатством, блеском и выразительными деталями.\n\nПо словам гостей, коктейль выглядит ярко, празднично и эффектно. Золотые кондитерские блёстки отражают свет и напоминают о позолоченных элементах барочных интерьеров, а фирменная печать на льду завершает визуальную композицию.\n\nВ основе напитка лежит формула White Negroni, переосмысленная в русской концепции бара. Практически каждый классический компонент здесь либо дополнен новым ароматом, либо заменён другим ингредиентом.\n\nДжин настаивается на клюкве холодным способом. Благодаря этому ягода добавляет тонкий аромат и лёгкую фруктовую терпкость, не окрашивая напиток слишком интенсивно.\n\nБелый вермут на саган-дайля приносит травяной, пряный и слегка бальзамический профиль. Вместо классического Suze используется белорусский аперитив Chemer Gold с фруктовыми оттенками и ароматом иланг-иланга.\n\nЧтобы сохранить обязательную для Negroni горечь, автор использует концентрат из сухого игристого вина и тоника. Смесь выпаривается втрое, становясь более насыщенной и позволяя внести горько-танинный элемент без существенного разбавления коктейля.\n\nВ результате получается крепкий, сладко-горький и травянистый напиток с тонкими нотами клюквы, саган-дайля, фруктов и цветов.',
