      story:
        'В баре Soil есть раздел Seasonal, где напитки меняются каждый месяц. В этой части меню команда работает с растительными ингредиентами на пике их созревания, стараясь показать сезон не только через вкус, но и через настроение.\n\nИюньский Стронг — это июньская вариация на Negroni. Летняя, яркая и собранная вокруг ягодно-цветочного профиля.\n\nКлассическая структура коктейля сохраняется: джин отвечает за крепкую основу, красный вермут — за винную сладость и глубину, Campari — за узнаваемую горечь. Но дальше классика раскрывается через сезонные акценты.\n\nКордиал из свежей черешни делает вкус более сочным, фруктовым и живым. Гидролат цветов черёмухи добавляет тонкий цветочный аромат и ощущение начала лета. Какао биттер работает как небольшой штрих в послевкусии: он не уводит напиток в десертность, а добавляет глубину и сухую сложность.\n\nИюньский Стронг — это Negroni, посмотревший в сторону сезона. Он остаётся плотным и серьёзным по конструкции, но звучит легче, свежее и ярче благодаря черешне и цветам черёмухи.',
