        'Twin Negroni — крепкий фруктово-винный твист на Negroni, построенный вокруг идеи внутреннего двойника. Джин и Campari сохраняют узнаваемую горькую основу, водка с маракуйей добавляет тропическую яркость, а красный портвейн — сладость, плотность и тёмный фруктовый профиль.',
      story:
        'Twin Negroni — история двойника в бокале.\n\n«Один глоток — и ты уже не один».\n\nЭтот коктейль становится зеркалом, в котором отражается второе «я». Сначала вкус кажется знакомым: горьковатая мягкость Negroni, джиновая структура, сладость и характерная красная горечь Campari.\n\nНо затем появляется другой голос. Водка с маракуйей делает композицию ярче и провокационнее, а красный портвейн добавляет тёмную фруктовую сладость и глубину.\n\nКлассический Negroni здесь олицетворяет дневную версию человека: собранную, элегантную и слегка ироничную. Его двойник просыпается ночью. Он говорит громче, смеётся резче и решается на то, о чём дневная версия только думает.\n\nС каждым глотком граница между двумя характерами становится тоньше. К финалу уже сложно понять, кто управляет этим диалогом и кто кого допивает.\n\nTwin Negroni — разговор с той версией себя, которую человек редко выпускает на свет.\n\nВыпьешь ты — или выпьет он?',
