      story:
        'Название Pommac Grace построено на соединении двух образов.\n\nПо авторской задумке, Pommac отсылает к гранатовому яблоку и подчёркивает роль граната в ароматическом профиле напитка. Grace переводится как «изящество» или «грациозность» и передаёт характер коктейля — тонкий, выразительный и утончённый.\n\nВ основе напитка лежит знакомая структура Negroni, переосмысленная через мак, цветы граната и шиповник.\n\nДжин, настоянный на семенах мака, формирует мягкую крепкую основу с деликатным орехово-зерновым оттенком. Розовый вермут на цветах граната и ягодах шиповника добавляет цветочную ароматику, фруктовую глубину и лёгкую терпкость. Campari сохраняет узнаваемую горечь и связывает композицию с классической формулой Negroni.\n\nАвторская история переносит гостя в вымышленный мир Макинии, где учёный Сэмюэль искал новые вкусы и после одного из путешествий привёз секретный рецепт Pommac Grace. Соединив джин на маке с вермутом на цветах граната и шиповнике, он создал напиток, ставший символом дружбы, открытий и магии момента.\n\nPommac Grace — коктейль о любопытстве и поиске нового вкуса. В нём мягкость маковых полей встречается с цветочной глубиной граната, ягодной терпкостью шиповника и классической горечью Campari.',
