      barDescription:
        'Олег Антонов создал Ragnar’s Negroni как многослойное посвящение образу викинга и философии северного воина. Джин на тимутском перце даёт пряную и цитрусовую основу, кумкват в вермутном миксе усиливает фруктовую терпкость, Campari сохраняет аперитивную горечь, а эликсир каламанси–пало санто добавляет экзотическую кислотность и древесную глубину. Гарниш в виде зелёного мха из бисквита и кондитерской жемчужины завершает образ напитка как авторского ритуального эликсира.',
