      barDescription:
        'Данила Щеголев создал BANANO-TORINO как демонстрацию комплексной работы с продуктами, потерявшими товарный вид. В коктейле используется мякоть переспелых бананов для осветлённого сока и кожура для ароматного олеосахарума. Банановая основа соединяется с переосмысленной формулой Milano–Torino, миксом кислот и солевым раствором. Напиток показывает, как ингредиент, предназначенный для списания, может стать основой технологичного авторского коктейля.',
