      intro:
        'BANANO-TORINO — авторская интерпретация Milano–Torino, посвящённая осознанной работе с продуктами, потерявшими товарный вид. Переспелые бананы используются комплексно: мякоть превращается в осветлённый сок, а кожура — в насыщенный олеосахарум. Банановый профиль соединяется с горечью Campari, пряностью красного вермута и выверенной кислотностью.',
      story:
        'Главная тема BANANO-TORINO — фудшеринг и рациональная работа с продуктами, которые потеряли привлекательный внешний вид, но сохранили вкус и аромат.\n\nПереспелые, потемневшие бананы часто остаются без покупателя. Их списывают, выбрасывают и заменяют новой партией, увеличивая объём пищевых отходов и углеродный след продукта.\n\nКоманда бара More решила показать, что такой ингредиент не теряет ценности. Напротив, по мере созревания банан становится ароматнее, слаще и выразительнее, что открывает возможности для его использования в коктейлях.\n\nВ BANANO-TORINO продукт перерабатывается практически целиком. Мякоть банана используется для приготовления осветлённого сока, а кожура — для ароматного олеосахарума. Такой подход помогает раскрыть разные части одного ингредиента и сократить количество отходов.\n\nАлкогольная основа строится на классическом сочетании Milano–Torino — красного вермута и Campari. После обработки в роторном испарителе она становится основой для более лёгкого и деликатного прочтения классического горько-сладкого профиля.\n\nБанановый сок добавляет фруктовый объём, олеосахарум усиливает аромат спелой кожуры, микс кислот поддерживает свежесть, а солевой раствор делает вкус более собранным.\n\nBANANO-TORINO показывает, что продукт с несовершенным внешним видом может стать основой сложного и технологичного коктейля.',
