      intro:
        'Sorso di Caffè — кофейно-вишнёвая вариация на Negroni, вдохновлённая фильмом «Укрощение строптивого». Campari и джин формируют крепкую горько-травяную основу, сухой вермут на вишне добавляет фруктовую терпкость, а кофейный эликсир раскрывает обжаренные и сладковато-пряные оттенки.',
      story:
        'Название Sorso di Caffè переводится с итальянского как «глоток кофе».\n\nИсточником вдохновения для коктейля стал фильм «Укрощение строптивого» и сцена, в которой главный герой делает глоток кофе, после чего опрокидывает напиток на бармена. Этот короткий комедийный эпизод определил кофейную тему и итальянское настроение коктейля.\n\nВ основе рецепта сохраняется узнаваемая логика Negroni. Campari отвечает за выразительную цитрусово-травяную горечь, джин «Целовальник» формирует крепкий ботанический каркас, а Cinzano Extra Dry, настоянный на вишне, добавляет сухой винный профиль, фруктовую терпкость и мягкую ягодную глубину.\n\nКофейный эликсир «Целовальник» становится главным тематическим акцентом. Он связывает сладость, горечь и аромат обжаренного кофе, делая композицию более насыщенной и продолжительной.\n\nАпельсиновый ринг и лист завершают подачу свежей цитрусовой ароматикой и поддерживают итальянский аперитивный характер напитка.',
