      intro:
        'Крепкий равнодольный коктейль, вдохновлённый фантастической историей о противостоянии Империи и Сопротивления. В авторской версии R2-D2 становится автоматом по приготовлению энергетического эликсира, который помогает героям приблизиться к победе.',
      story:
        'Где-то в далёкой галактике Империя готовится нанести ответный удар, а силы Сопротивления собирают последние ресурсы для решающего сражения.\n\nВ этой версии истории R2-D2 выполняет новую задачу. Он становится автоматом по приготовлению особого энергетического эликсира — напитка, который должен вернуть героям силы, поддержать боевой дух и помочь приблизить победу.\n\nВнутри его металлического корпуса соединяются три компонента в равных пропорциях: Legate, Martin Fierro и Barrister Ray. Получается крепкая и выразительная композиция с высокой горечью и плотным характером.\n\nНапиток превращает знакомый образ дроида-помощника в часть барной фантазии: теперь R2-D2 не только передаёт секретные данные и помогает Сопротивлению, но и отвечает за приготовление эликсира перед решающей битвой.',
