      story:
        'Velvet родился на стыке суровой текстильной истории и мягкой гастрономии.\n\nИваново известно как город тканей и город невест. Эти два образа стали отправной точкой для коктейля, который передаёт местную идентичность через вкус и текстуру. Автор представляет напиток как гастрономический аналог бархата — плотного, мягкого и меняющего оттенок в зависимости от движения и света.\n\nВ основе коктейля — ягодный аперитив «Чемер» с малиной и черникой. Он создаёт выразительный фруктовый слой и поддерживает насыщенный цвет напитка. Campari добавляет аккуратную цитрусово-травяную горечь.\n\nЛактоводка, приготовленная с клубничным питьевым йогуртом, делает профиль более мягким и округлым. После фильтрации в ней сохраняются ягодные и молочные оттенки, но текстура становится чище. Молочный кордиал добавляет контролируемую кислотность и отсылает к знакомым кисломолочным напиткам из детства.\n\nVelvet раскрывается постепенно. Сначала появляется ягодная сладость, затем мягкая молочная кислотность, а в финале остаётся лёгкая горечь. Напиток выглядит понятным, но внутри объединяет локальную историю, гастрономические воспоминания и работу с текстурой.\n\nОн простой снаружи и сложный внутри — как сам город.',
