      story:
        'Идея Artisanal Negroni появилась во время обычной прогулки в парке. Автор хотел соединить в одном напитке аромат чёрной смородины, выраженную травянистость, лёгкую кислотность рислинга и прохладную свежесть мяты.\n\nНа концепцию также повлиял ресторан «Огонёк моей души», где напитки посвящены Иванову и окружающим его районам. Локальная тема может раскрываться через сорта яблок, ромашковые поля, уютные городские улицы, традиционные блюда и знакомые с детства вкусы.\n\nВ этом коктейле Иваново показано без излишней сладости и декоративности. Его настроение меняется от глотка к глотку, но остаётся узнаваемым.\n\nДистиллят из листьев и ветвей чёрной смородины создаёт сухую ягодно-ботаническую основу. Мятный рислинг добавляет винную кислотность и прохладный травяной аромат. Suze усиливает горечь, а авторский кордиал на молочной кислоте объединяет компоненты и делает вкус собраннее.\n\nГарнир из бальзамических жемчужин добавляет концентрированную кисло-сладкую ноту, а скелетированный лист поддерживает природную и ремесленную эстетику подачи.',
