      story:
        'Картли-Негрони создан как авторский взгляд на классический Negroni через вкусы и атмосферу грузинского застолья.\n\nПо легенде коктейля, многие алхимики пытались найти идеальный аперитив, способный соединить крепкий напиток на фейхоа со сладким ароматизированным вином. Итогом этого поиска стала композиция, предназначенная для долгого застолья, дружеских встреч и шумных соседских вечеров.\n\nДистиллят фейхоа формирует крепкую фруктовую основу с характерной терпкостью. Белый вермут добавляет мягкость, винную сладость и ароматическую лёгкость. Аперитив «Чемер» фейхоа–тархун усиливает тропический профиль и приносит свежие травяные оттенки. Молочный кордиал отвечает за кислотность, баланс и более округлое восприятие вкуса.\n\nСушёный инжир завершает подачу и поддерживает южный фруктовый характер напитка.\n\nНазвание отсылает к Картли, которую автор представляет как одну из центральных историко-географических областей и колыбель грузинской культуры. Благодаря этому коктейль становится образом не только конкретного вкуса, но и гостеприимства, открытого стола и совместного вечера.',
