        'У каждого знакового коктейля есть собственная история. У «Татарского Негрони» она начинается с вопроса: каким мог бы стать классический Negroni, если бы его создавали в самом сердце Татарстана?\n\nОтвет нашёлся среди знакомых ароматов местного рынка: кураги, мёда, чернослива и душистого разнотравья.\n\nВладислав Туманин искал сочетание, которое сохранило бы равнодольную структуру Negroni, но наполнило её локальным содержанием. Для крепкой части джин настаивается на кураге и мёде от местных пасечников. Курага добавляет мягкую фруктовую глубину, а мёд — округлость и тёплый аромат.\n\nКлассическая горькая часть переосмыслена через Campari, настоянный на черносливе и татарском разнотравье. Травы для заготовки собирает Халима апа — на своём участке и в окрестных лесах. Чернослив делает горечь более тёмной и фруктовой, а травы добавляют ощущение лугов, леса и местной ботаники.\n\n«Бугульма Премиум» становится связующим элементом и поддерживает тему татарского гостеприимства. Все три компонента соединяются в равных пропорциях, сохраняя понятную и строгую архитектуру классического коктейля.\n\nПодача продолжает историю. Вместе с напитком появляются курага, чернослив и чак-чак — традиционная татарская сладость, связанная с праздником, общим столом и приёмом гостей.\n\n«Татарский Негрони» объединяет итальянскую коктейльную формулу с локальными продуктами, семейными историями и вкусами Казани.',
      image: '/images/recipes/Tatar Negroni.png',
