        'The Lotus Path — дальневосточная интерпретация Negroni, в которой российский джин соединяется с кордиалом из корня лотоса, грейпфрута и молочного улуна, Martini Bitter и розовым вермутом на карамелизированном пекане. Коктейль раскрывается от яркой фруктово-цитрусовой свежести к травяной горечи, землистым оттенкам лотоса и тёплому орехово-карамельному финалу.',
      story:
        'The Lotus Path — медитативное путешествие вкуса на Дальний Восток, где встречаются русская природа, восточная культура и итальянская аперитивная традиция.\n\nПуть начинается с российского джина «Целовальник». В авторском описании его профиль напоминает о спелом яблоке, чёрной смородине и свежей крапиве — вкусах садов, лесов и диких лугов.\n\nДалее композиция перемещается на Дальний Восток через кордиал из маринованного корня лотоса, грейпфрутовой цедры и молочного улуна. Корень лотоса добавляет землистый, растительный характер, грейпфрут — цитрусовую свежесть и лёгкую горечь, а чай формирует мягкий сливочно-карамельный ароматический оттенок.\n\nСвязь с классическим Negroni поддерживает Martini Bitter. Он приносит узнаваемую травяную горечь и сохраняет аперитивную структуру напитка.\n\nMartini Rosato, настоянный на карамелизированном пекане, отвечает за мягкость и тёплый финал. Ягодно-цветочный профиль розового вермута дополняется ореховыми, маслянистыми и карамельными нотами.\n\nПряный чипс из корня лотоса становится символом пройденного пути. Он возвращает гостя к главному образу коктейля и добавляет подаче сладкие, кислые и перечные оттенки.\n\nСначала The Lotus Path раскрывается ярко и фруктово, затем появляются лотос, чай и горькие травы, а в послевкусии остаются пекан, карамель и мягкая винная сладость.',
