      intro:
        'Far East Negroni — гастрономическая интерпретация классического коктейля, посвящённая Владивостоку. Barrister Far East Gin соединяется с Campari на ягодах лимонника и авторским блендом красного вермута, умешу, саке, зелёного чая, рисового уксуса и имбиря. Напиток сопровождается маринованным приморским гребешком, раскрывающим его морской и дальневосточный характер.',
      story:
        'Far East Negroni — вкусовое воспоминание Сергея Шикуева о Владивостоке, городе, в котором он прожил восемь лет.\n\nЗдесь Азия и Европа встречаются ежедневно: в городской архитектуре, продуктах, кухне и напитках. Именно это культурное пересечение стало основой коктейля.\n\nОтправной точкой стал Barrister Far East Gin с юдзу, чаем и специями. Его профиль позволил сохранить связь с классической джиновой основой Negroni и одновременно передать характер региона.\n\nCampari на ягодах лимонника добавляет яркую горечь, терпкость и характерный ягодно-травяной акцент. Лимонник поддерживает образ дальневосточных лесов и делает привычный итальянский биттер более локальным по звучанию.\n\nАвторский вермутный бленд объединяет европейскую и азиатскую традиции. Красный сладкий вермут отвечает за винную пряность, умешу — за сливовую фруктовость, саке — за мягкость, а концентрат зелёного чая добавляет сухость и растительную терпкость. Рисовый уксус и имбирная настойка формируют лёгкий гастрономический акцент и делают вкус собраннее.\n\nМаринованный приморский гребешок завершает концепцию. Он подаётся на деревянной ложке поверх бокала и превращает коктейль в небольшую композицию, где аперитивная горечь встречается с морской сладостью и умами.\n\nFar East Negroni — это Владивосток в бокале: морской воздух, лесной лимонник, чай, саке и европейская классика, прочитанная через вкусы Дальнего Востока.',
