      story:
        'Grape × 3 Enzoni появился как альтернатива для гостей, которым классический Negroni кажется слишком крепким или предсказуемым.\n\nИсточником вдохновения стали воспоминания Егора Ширяева о летних поездках за город и домашнем виноделии. Виноград собирали всей семьёй, а затем наблюдали, как в больших стеклянных сосудах постепенно созревает вино и на горлышке надувается резиновая перчатка.\n\nОсобенным моментом была первая проба молодого напитка — сладкого, концентрированного и ещё не до конца сформировавшегося. Его разрешали попробовать совсем немного, обязательно сопровождая словами: «Только не много — тебе ещё рано».\n\nЭти воспоминания о лете, урожае и домашнем вине стали основой вкусовой концепции.\n\nВермут Carpano Classico формирует сладкую винную часть, Carpano Botanic и Campari создают несколько уровней горечи, а джин Hoppers сохраняет ботанический каркас классического коктейля.\n\nВиноградная тема раскрывается сразу в нескольких формах: виноградный соджу, концентрированный виноградный сок и выдержанный бальзамический уксус из виноградного сусла. Так появляется заложенное в названии Grape × 3 — виноградный профиль, умноженный на три. Маринованный виноград в гарнире становится дополнительным продолжением этой темы.\n\nКоктейль сохраняет узнаваемую горько-сладкую конструкцию, но звучит мягче, фруктовее и легче по восприятию.\n\nВинная основа: Carpano Classico добавляет сладость, травяные оттенки, специи и насыщенный профиль красного вермута.\n\nГорькая часть: Carpano Botanic и Campari создают многослойную горечь — травяную, цитрусовую и пряную.\n\nКрепкая часть: джин Hoppers поддерживает структуру коктейля и добавляет можжевеловые и ботанические оттенки.\n\nВиноградный профиль: виноградный соджу формирует лёгкую фруктовую основу, концентрированный сок усиливает сладость и аромат, а бальзамический уксус добавляет кислотность, глубину и выдержанные оттенки виноградного сусла.\n\nГарнир: маринованный виноград продолжает основную тему и добавляет кисло-сладкий, пряный гастрономический акцент.',
      image: '/images/recipes/Grape × 3 Enzoni.png',
