      intro:
        'Midnight Negroni — десертная вариация на классический коктейль с тёмным шоколадом и апельсином. Джин, Campari и красный вермут сохраняют узнаваемую горько-травяную основу, коричневый Crème de Cacao добавляет насыщенный шоколадный профиль, а Cointreau — яркий цитрусовый аромат.',
      story:
        'Полночь — время романтики и тайн, которые скрываются в привычной темноте.\n\nЭто момент, когда перестаёшь смотреть на часы и начинаешь говорить о том, что при дневном свете могло бы показаться слишком личным или неуместным. Именно такому состоянию посвящён Midnight Negroni.\n\nИдея напитка появилась примерно за пять лет до того, как Анастасия начала профессионально интересоваться коктейлями. Во время позднего ужина на двоих в барной карте оказался напиток с тёмным шоколадом. Этот вкус особенно понравился близкому человеку и постепенно превратился в воспоминание, которое хотелось сохранить в собственной рецептуре.\n\nТак появился шоколадно-апельсиновый твист на Negroni.\n\nДжин формирует сухую ботаническую основу. Campari сохраняет узнаваемую горечь, а красный сладкий вермут добавляет винную мягкость и пряность. Коричневый Crème de Cacao раскрывает насыщенные оттенки тёмного шоколада и делает текстуру более округлой. Небольшая порция Cointreau добавляет свежую цитрусовую ароматику и связывает шоколад с апельсиновой темой классического Negroni.\n\nАпельсиновая цедра закрепляется снаружи бокала прищепкой. Благодаря этому она становится не только ароматическим элементом, но и частью визуального образа — словно тонкая линия света на фоне ночной темноты.\n\nMidnight Negroni сохраняет воспоминание о позднем ужине, близком человеке и вкусе, который однажды стал личным.\n\nКрепкая основа: джин создаёт сухой ботанический каркас и поддерживает классическую структуру коктейля.\n\nШоколадная часть: коричневый Crème de Cacao добавляет насыщенный какао-профиль, сладость и десертную округлость.\n\nГорькая часть: Campari формирует цитрусово-травяную горечь и не позволяет шоколадной части сделать напиток чрезмерно сладким.\n\nЦитрусовая часть: Cointreau и апельсиновая цедра добавляют эфирную свежесть и подчёркивают сочетание шоколада с апельсином.\n\nВинная часть: красный сладкий вермут связывает горечь, шоколад и цитрус пряным ароматизированным винным профилем.',
      image: '/images/recipes/Midnight Negroni.png',
      cardImage: '/images/cards/Midnight Negroni.png',
