      intro:
        'Kimchi Ttalgi — авторская вариация на Negroni с корейским характером. Джин на кимчи, красный вермут на клубнике, Campari и клубничный соджу создают сочетание глубокой умами-ферментации, ягодной сладости и бархатистой горечи.',
      story:
        'Kimchi Ttalgi построен на контрасте, который неожиданно оказывается очень цельным.\n\nВ основе идеи — соединение двух ярких вкусовых миров: ферментированной, солёно-кислой глубины кимчи и сочной, мягкой сладости клубники. Вместо того чтобы спорить друг с другом, эти вкусы выстраиваются в многослойную композицию.\n\nДжин на кимчи формирует необычную гастрономическую основу. Он приносит остроту, ферментированную глубину, солоноватые оттенки и характерный умами-профиль. Красный вермут на клубнике смягчает эту мощь, добавляя ягодную сладость, аромат свежей клубники и более округлую винную структуру.\n\nCampari сохраняет узнаваемую горькую ось классического Negroni, а клубничный соджу усиливает фруктовую тему и делает напиток более питким. Солевой раствор помогает собрать вкус воедино и подчёркивает и умами, и фруктовую часть.\n\nПо описанию автора, это четыре вкуса и один характер: сладость, горечь, кислотность и умами соединяются в напитке, который звучит смело, но при этом остаётся гармоничным.\n\nУмами-основа: джин на кимчи даёт солёно-кислые ферментированные ноты, пряность и выраженную гастрономическую глубину.\n\nЯгодная часть: красный вермут на клубнике и клубничный соджу формируют сладко-фруктовый слой и смягчают интенсивность кимчи.\n\nГорькая часть: Campari отвечает за классическую аперитивную горечь и балансирует сладкие и ферментированные оттенки.\n\nСолевой баланс: несколько дэшей солевого раствора усиливают объём вкуса и подчёркивают умами-компоненты.\n\nФинал: послевкусие плотное, чуть солоноватое, ягодное и горьковатое, с мягким гастрономическим шлейфом.',
