      intro:
        'Twist Me Gently — летняя вариация на Negroni с ароматом земляники, розы и спелого персика. Розовый джин, авторский ягодно-травяной биттер и два вида сладкого вермута сохраняют крепкую горько-сладкую структуру классики, а фруктовая ароматика делает коктейль легче по восприятию.',
      story:
        'Twist — это изменение знакомой коктейльной классики. Но у этого слова есть и другое значение: неожиданный поворот, небольшая иллюзия, обман ожиданий.\n\nИменно на этом построен Twist Me Gently.\n\nПо аромату коктейль кажется мягким и сладким. В первую очередь раскрываются земляника, роза и спелый персик. Однако за фруктовым ароматом сохраняется крепкий и выразительно горький профиль, близкий к классической формуле Negroni.\n\nРозовый джин создаёт ягодно-ботаническую основу. Авторский биттер из земляники и чайной розы добавляет одновременно фруктовую сладость, цветочную ароматику и сухую горечь полыни, аира и цитрусовой цедры.\n\nКрасный и белый сладкие вермуты используются в равных пропорциях. Красный отвечает за пряность и насыщенность, а белый делает винную часть светлее и мягче. Небольшое количество персикового ликёра усиливает аромат, не превращая напиток в очевидно десертный.\n\nКоктейль задуман для тёплой погоды — как более ароматная и лёгкая по восприятию версия Negroni. При этом его крепость и горечь остаются достаточно выраженными.\n\nЭто всё ещё Negroni — просто gently twisted.\n\nЯгодно-ботаническая основа: розовый джин формирует можжевеловый каркас с ягодными и цветочными оттенками.\n\nЗемлянично-цветочная часть: сублимированная земляника и чайная роза создают яркий аромат, который воспринимается слаще, чем фактический вкус напитка.\n\nГорькая часть: полынь и корень аира добавляют сухую травяную и корневую горечь. Кардамон и апельсиновая цедра поддерживают пряно-цитрусовый профиль.\n\nВинная часть: красный сладкий вермут придаёт плотность и специи, а белый сладкий вермут — более лёгкие цветочные и фруктовые оттенки.\n\nПерсиковый акцент: персиковый ликёр используется в небольшой дозировке и усиливает аромат спелого фрукта, сохраняя основную горькую структуру.',
