      story:
        'The Real Answer был создан Дарьей Куксиной для гостевой смены в баре O.W. Grant. Источником вдохновения стал фильм «Трасса 60» и путь его главного героя к пониманию того, что он действительно искал.\n\nКоктейль становится финальной точкой условного путешествия по эволюции горечи. Здесь горечь уже не воспринимается как испытание или сложный элемент, который необходимо преодолеть. Она становится осознанной частью композиции — зрелой, многослойной и цельной.\n\nCampari формирует центральную горько-цитрусовую линию. Courvoisier VS добавляет виноградную глубину, дубовые оттенки и мягкую пряность. Grand Marnier Cordon Rouge связывает коньячную основу с ароматом апельсина и добавляет округлую сладость.\n\nКофейная тинктура усиливает тёмную сторону напитка: появляются обжаренные, землистые и слегка шоколадные ноты. Табачный парфюм работает преимущественно через аромат и создаёт ассоциации с сухим листом, древесиной и старой кожей.\n\nВ авторской концепции этот коктейль символизирует момент принятия реальности без иллюзий. Путь к ответу проходит через опыт, а опыт почти всегда содержит свою долю горечи.\n\nКак и в классическом Negroni, горечь здесь не декоративный элемент. Она является основой вкуса и главным смысловым инструментом.\n\nГорькая часть: Campari создаёт выраженную цитрусово-травяную горечь и формирует основную структуру напитка.\n\nКоньячная часть: Courvoisier VS добавляет оттенки винограда, сухофруктов, дуба и мягких специй.\n\nАпельсиновая часть: Grand Marnier Cordon Rouge усиливает аромат апельсиновой цедры, добавляет сладость и связывает Campari с коньяком.\n\nКофейная часть: кофейная тинктура формирует обжаренный профиль с оттенками тёмного шоколада, какао и молотого кофе.\n\nТабачный аромат: табачный парфюм создаёт сухую ароматическую рамку с древесными, пряными и кожаными ассоциациями.\n\nФинальный баланс: предварительное разбавление смягчает спиртуозность и позволяет сразу получить стабильную текстуру при подаче методом build.',
