        'G Negroni — ягодно-травяная интерпретация классического коктейля, вдохновлённая волжским летом. Джин на лемонграссе, белый вермут на клубнике и Campari на черешне создают свежий, ароматный и многослойный профиль с цитрусовыми травами, спелыми ягодами и узнаваемой аперитивной горечью.',
      story:
        'История G Negroni началась летним вечером с вопроса: как сохранить характер классического Negroni, но сделать его отражением конкретного места?\n\nОтвет Илья Асланиди нашёл в ароматах волжского лета — свежей черешне с местных рынков, спелой клубнике и ярком, цитрусово-травяном лемонграссе.\n\nКаждая часть классической формулы получила собственный ароматический акцент.\n\nДжин настаивается на мелко нарезанном лемонграссе. Он сохраняет крепкий ботанический каркас, но приобретает свежие цитрусовые, травяные и слегка пряные оттенки.\n\nБелый вермут соединяется с клубникой. Ягода добавляет мягкую сладость, сочность и летнюю ароматику, а светлый вермут сохраняет винную лёгкость и цветочный характер.\n\nCampari на черешне отвечает за тёмную ягодную глубину. Черешня смягчает цитрусово-травяную горечь биттера, не разрушая его узнаваемую структуру.\n\nВ результате классический Negroni звучит ярче и фруктовее, но остаётся крепким, глубоким и выразительным.\n\nПо замыслу автора, G Negroni передаёт характер самого G Lounge: дерзкий, тёплый и немного романтичный. Напиток стал отражением бара и вкусовым воспоминанием о лете на Волге.\n\nЦитрусово-травяная основа: джин на лемонграссе создаёт свежий ботанический профиль с оттенками лимонной цедры, зелёных трав и пряных эфирных масел.\n\nЯгодно-винная часть: белый вермут на клубнике добавляет мягкую сладость, цветочность и аромат спелых ягод.\n\nГорько-фруктовая часть: Campari на черешне сохраняет классическую аперитивную горечь, дополненную тёмными ягодными и косточковыми оттенками.\n\nБаланс: равнодольная формула сохраняет понятную структуру Negroni, а три отдельных настоя делают вкус более летним и ароматным.',
