      intro:
        'Арахисовый Негрони — насыщенная орехово-шоколадная интерпретация классического коктейля. Арахисовый дистиллят соединяется с сухим вермутом, белым биттером Luxardo и белым какао-ликёром, создавая крепкий и округлый вкус с оттенками жареного арахиса, шоколада, трав и мягкой горечи.',
      story:
        'Арахисовый Негрони предлагает посмотреть на классическую горько-сладкую структуру через сочетание орехов и шоколада.\n\nВместо традиционной джиновой основы используется арахисовый дистиллят. Его получают из водки и арахисовой пасты с помощью роторного испарителя, стремясь перенести в прозрачную алкогольную основу аромат жареного ореха без тяжёлой текстуры исходного продукта.\n\nСухой вермут добавляет винную свежесть, травяные оттенки и делает композицию менее сладкой. Белый биттер Luxardo отвечает за аперитивную горечь, а белый какао-ликёр формирует шоколадный слой и округляет крепкую основу.\n\nПо авторскому замыслу сочетание арахиса и какао вызывает ассоциацию с шоколадно-арахисовым десертом. При этом сухой вермут и биттер удерживают напиток в стилистике Negroni, не позволяя ему превратиться в обычный сладкий коктейль.\n\nВ результате получается крепкий, насыщенный и продолжительный напиток с ореховым началом, шоколадной серединой и мягким травяно-горьким финалом.\n\nАрахисовая основа: арахисовый дистиллят формирует ведущий аромат жареного ореха и крепкий алкогольный каркас.\n\nВинно-травяная часть: сухой вермут добавляет лёгкую винную кислотность, травы и более сухое развитие вкуса.\n\nГорькая часть: белый биттер Luxardo создаёт мягкую цитрусово-травяную горечь и поддерживает аперитивный характер коктейля.\n\nШоколадная часть: белый какао-ликёр добавляет сладость, ванильно-какаовую ароматику и округлую текстуру.\n\nПослевкусие продолжительное, орехово-шоколадное, с умеренной травяной горечью и выраженной крепостью.',
      image: '/images/recipes/Peanut Negroni.png',
