          'Проводить перегонку только обученным сотрудником. Параметры (температура бани, давление, скорость вращения, охлаждение, объём загрузки, время, отбор фракции) уточняются у автора.',
          'Отделить и сохранить нужную ароматическую фракцию. Не перегонять смесь досуха.',
