      story:
        'LAURA BIAGIOTTI — коктейль, в котором вкус раскрывается через язык итальянской моды.\n\nВ авторской концепции напиток воплощает мягкую силу, сдержанную элегантность и внимание к деталям. Его композиция напоминает вечерний образ: строгая основа, выверенные пропорции и один глубокий акцент, который меняет восприятие всей работы.\n\nПятилетний бренди Torres формирует тёплый виноградно-древесный каркас. Luxardo Bitter добавляет аперитивную горечь, а Martini Rosso — винную сладость, травы и специи.\n\nНебольшая порция Sangue Morlacco раскрывается оттенками тёмной вишни и косточки. Ликёр не становится самостоятельным десертным слоем, а подчёркивает глубину бренди и соединяет его с горько-пряной частью коктейля.\n\nКисло-сладкий кордиал завершает баланс, добавляя точечную сладость и кислотность. Благодаря небольшой дозировке напиток сохраняет строгую и собранную структуру.\n\nФинальной деталью становится кожаный ремешок ручной работы — декоративная отсылка к миру модных аксессуаров, в котором каждая деталь является частью общего образа.\n\nLAURA BIAGIOTTI не требует лишних объяснений. Он говорит стилем.\n\nВыдержанная основа: пятилетний бренди Torres добавляет виноградные, дубовые, пряные и слегка карамельные оттенки.\n\nГорькая часть: Luxardo Bitter формирует сухую цитрусово-травяную горечь и поддерживает аперитивную структуру напитка.\n\nВинная часть: Martini Rosso добавляет сладость, специи и насыщенный профиль красного ароматизированного вина.\n\nВишнёвый акцент: Sangue Morlacco привносит аромат тёмной вишни, косточковые оттенки и дополнительную глубину.\n\nКисло-сладкий баланс: авторский кордиал смягчает горечь и добавляет лёгкую кислотность, сохраняя общую композицию собранной.',
