      intro:
        '«Хотей» — мягкая ягодно-травяная вариация на Negroni, созданная для первого знакомства с горько-сладкой классикой. Йогуртовый дистиллят на красном базилике соединяется с клубничным блендом на основе Campari, рислингом и клубничным сиропом. Получается лёгкий, фруктовый и умеренно горький коктейль с винной кислотностью и свежей травяной ароматикой.',
      story:
        'Коктейль «Хотей» был создан для меню Good Karma Bar, посвящённого богам и демонам.\n\nВ авторской концепции напиток обращается к образу Хотэя — широко улыбающегося странника с большим животом и веером, связанного в японской традиции со счастьем, благополучием и умением отгонять несчастья.\n\nЭтот образ определил и характер коктейля. Напиток задуман дружелюбным, мягким и открытым — таким, который помогает гостю начать знакомство с Negroni без избыточной крепости и агрессивной горечи.\n\nВместо классического джина используется дистиллят из водки и питьевого йогурта, дополнительно ароматизированный красным базиликом. Дистилляция должна переносить в прозрачную алкогольную основу мягкий кисломолочный аромат, а базилик добавляет свежие травяные, пряные и слегка ягодные оттенки.\n\nЗа горько-фруктовую часть отвечает бленд Campari, клубничного пюре и Martini Fiero. Клубника смягчает горечь, а Fiero поддерживает композицию цитрусовыми и винными нотами.\n\nРислинг категории Kabinett добавляет кислотность, лёгкость и ароматическую свежесть. Небольшое количество клубничного сиропа округляет вкус и усиливает ягодную тему.\n\nВ результате получается коктейль с узнаваемой логикой Negroni, но более мягкий, фруктовый и доступный для гостей, которые только начинают знакомиться с горькими аперитивами.\n\nЙогуртовая основа: йогуртовый дистиллят формирует мягкий молочно-кислый ароматический оттенок без тяжёлой текстуры исходного йогурта.\n\nТравяная часть: красный базилик добавляет свежую пряность, зелёные ноты и лёгкие оттенки гвоздики, аниса и тёмных ягод.\n\nГорько-клубничная часть: Campari сохраняет аперитивную горечь, клубничное пюре добавляет фруктовую насыщенность, а Martini Fiero усиливает цитрусово-винный профиль.\n\nВинная часть: рислинг Kabinett приносит свежую кислотность, лёгкую остаточную сладость и фруктово-цветочную ароматику.\n\nСладкая часть: клубничный сироп округляет кислотность и усиливает ощущение спелой ягоды.',
