      barDescription:
        'Андрей Усольцев создал коктейль «Марина Цветаева» как соединение литературного образа, сезонной рябины и личных воспоминаний. Джин и красный вермут сохраняют связь с горько-сладкой классикой, а кордиал из рябины и хризантемы формирует насыщенный ягодно-цветочный профиль. Подача в бокале-тюльпане и цветочный гарнир продолжают образ романтики и меланхолии Серебряного века.',
