      intro:
        '«Марина Цветаева» — рябиново-цветочная вариация на горько-сладкую коктейльную классику. Сухой джин соединяется с Martini Rosso и насыщенным кордиалом из красной рябины и хризантемы, создавая сладкий, терпкий и ароматный напиток с продолжительным ягодно-травяным послевкусием.',
      story:
        'Коктейль «Марина Цветаева» посвящён поэтессе Серебряного века — женщине, в стихах и судьбе которой соединяются сила, романтика и меланхолия.\n\nОтправной точкой для рецепта стала красная рябина. В авторской истории она связана как с образом Марины Цветаевой, так и с личными воспоминаниями Андрея Усольцева: в детстве он любил срывать и пробовать терпкие ягоды прямо с кисти.\n\nСезон рябины подсказал основу напитка, вдохновлённого формулой Negroni. Вместо традиционного итальянского биттера в композиции используется насыщенный кордиал из сушёной красной рябины и хризантемы.\n\nРябина добавляет сладко-терпкий ягодный характер, лёгкую горечь и ощущение поздней осени. Хризантема раскрывает цветочную и травяную часть, поддерживая литературный образ напитка и его сезонное настроение.\n\nGinster London Dry формирует сухую можжевеловую основу, а Martini Rosso добавляет винную сладость, специи и травы. Благодаря большой доле кордиала коктейль получается мягче и заметно слаще классического Negroni.\n\nПодача в бокале-тюльпане продолжает авторскую историю и напоминает форму, в которой могут подаваться настойки и ароматные дижестивы. Пыльца хризантемы завершает образ, усиливая цветочную ароматику напитка.\n\nДжиновая основа: Ginster London Dry создаёт сухой можжевелово-ботанический каркас и балансирует высокую сладость кордиала.\n\nВинно-травяная часть: Martini Rosso добавляет пряность, травы, мягкую горечь и насыщенность красного вермута.\n\nРябиновая часть: сушёная красная рябина формирует терпкий ягодный профиль с лёгкой горечью и оттенками сухофруктов.\n\nЦветочная часть: хризантема добавляет деликатную цветочную ароматику и растительные оттенки.\n\nКисло-сладкий баланс: сахар создаёт плотную основу кордиала, а лимонная кислота добавляет необходимую свежесть и не позволяет композиции стать полностью сиропной.',
      image: '/images/recipes/Marina Tsvetaeva.png',
