      intro:
        'The Carlton — фруктово-травяная интерпретация Negroni, созданная как вкусовое отражение бара и отеля. Два вида джина соединяются с манговым вермутом, биттером и двумя инфузиями Martini Fiero — на клубнике и зелёном базилике. Получается насыщенный коктейль с ягодной сладостью, тропическим акцентом и мягкой травяной горечью.',
      story:
        'В основе концепции The Carlton — образ двух львов, представленных в айдентике отеля.\n\nПо авторской задумке они символизируют единство и равенство между командой, которая сохраняет культуру гостеприимства, и гостями, которые становятся частью истории отеля. Это метафора тёплого контакта, доверия и отношений, способных продолжаться годами.\n\nДва льва также отражают встречу Востока и Запада — культурное пересечение, особенно заметное в Москве. Эта идея переносится в структуру коктейля, где узнаваемая европейская аперитивная классика соединяется с яркими фруктовыми и травяными вкусами.\n\nОснову напитка формируют два джина. Классический house gin отвечает за сухой ботанический каркас, а клубничный джин добавляет ягодную ароматику и мягкость.\n\nМанговый вермут создаёт тропический винный слой. Биттер сохраняет связь с горько-сладкой конструкцией Negroni, а Martini Fiero раскрывается сразу в двух направлениях: клубника усиливает фруктовую часть, зелёный базилик добавляет свежесть и растительную пряность.\n\nКрупный куб льда с печатью логотипа становится центральной частью подачи. Он поддерживает визуальную идентичность отеля и подчёркивает связь напитка с местом, для которого тот был создан.\n\nThe Carlton объединяет яркость современных вкусов с узнаваемой классической структурой — так же, как сам отель соединяет традицию, международную культуру и современную Москву.\n\nДжиновая основа: house gin создаёт сухой ботанический каркас, а клубничный джин добавляет более мягкий ягодный аромат.\n\nТропическая часть: манговый вермут формирует фруктовую сладость, винный объём и оттенки спелого тропического плода.\n\nГорькая часть: биттер отвечает за аперитивную горечь и удерживает композицию в стилистике Negroni.\n\nКлубничная часть: Martini Fiero на клубнике усиливает ягодный профиль и связывает клубничный джин с вермутной основой.\n\nТравяная часть: Martini Fiero на зелёном базилике добавляет свежие растительные, пряные и слегка перечные оттенки.\n\nБаланс: клубника и манго делают коктейль округлым и ароматным, а джин, биттер и базилик сохраняют сухость и горько-травяную структуру.',
