        'Игорь Донских создал «Мечту Грэя» как романтическое крымское прочтение Negroni для ресторана «Алые Паруса» на курорте «Сосновая Роща». Джин на местных травах формирует ботаническую основу, Campari на инжирном персике добавляет сочную фруктовость, а Martini Rosso на клубнике и ревене создаёт ягодно-винную глубину. Кордиал с сакурой, шисо и медовыми сотами связывает композицию с образом путешествия, ожидания и мечты из «Алых парусов».',
