      intro:
        '«Мечта Грэя» — крымская интерпретация Negroni, вдохновлённая романтикой «Алых парусов». Джин на крымских травах соединяется с Campari на инжирном персике, Martini Rosso на клубнике и ревене и кордиалом с сакурой, шисо и медовыми сотами. Вкус раскрывается травяной свежестью, спелыми фруктами, винной пряностью и продолжительной аперитивной горечью.',
      story:
        'В атмосфере дворцов и парков Южного берега Крыма классический Negroni получает новое прочтение.\n\nКоктейль «Мечта Грэя» был создан в ресторане «Алые Паруса», в пространстве, стилизованном под каюту корабля. Его история обращается к одноимённому произведению Александра Грина, где море, ожидание и мечта соединяются в один романтический образ.\n\nОсновой напитка становится Barrister 47, настоянный на сборе крымских трав. Он создаёт сухой ботанический каркас и передаёт аромат местной природы — нагретых солнцем трав, степных растений и пряной зелени.\n\nCampari на инжирном персике добавляет сочный фруктовый слой. Спелый крымский персик смягчает цитрусово-травяную горечь биттера, сохраняя его узнаваемый аперитивный характер.\n\nMartini Rosso на клубнике и ревене формирует винно-ягодную часть. Клубника приносит аромат спелых летних ягод, а ревень добавляет растительную свежесть и лёгкую кисловато-терпкую ноту.\n\nКордиал с сакурой, шисо и медовыми сотами завершает композицию. По авторской задумке он соединяет цветочность, пряную травянистость и мягкую медовую сладость.\n\nДекоративные соты становятся символом тщательно выстроенного мира, где каждая деталь поддерживает общую историю — от аромата крымского персика до романтики ночного путешествия под алыми парусами.\n\nКрымская ботаническая основа: джин на сборе крымских трав добавляет можжевеловые, пряные и растительные оттенки.\n\nПерсиково-горькая часть: Campari на инжирном персике сохраняет цитрусовую горечь, дополненную ароматом спелого фрукта и мягкой косточковой сладостью.\n\nЯгодно-винная часть: Martini Rosso на клубнике и ревене создаёт насыщенный профиль красного вермута с ягодными, пряными и растительными оттенками.\n\nЦветочно-травяная часть: сакура и шисо добавляют цветочную ароматику, зелёную пряность и лёгкие мятно-базиликовые ассоциации.\n\nМедовый акцент: медовые соты и предполагаемый медовый компонент кордиала смягчают горечь и поддерживают романтический, тёплый образ напитка.',
