      story:
        'Один из проектов Umami посвящён японской железнодорожной культуре. Барная карта построена как сеть маршрутов по Японии: каждый напиток становится отдельной остановкой, историей или достопримечательностью, до которой гость символически добирается на поезде.\n\nВажной частью концепции стала традиция Eki Stamp — памятных печатей, которые путешественники собирают на японских станциях. Поэтому подача коктейля превращается в небольшой ритуал: гостю выдают стилизованный билет, ставят на него печать с изображением поезда и рассказывают историю маршрута.\n\nКоктейль Kamaishi посвящён образу голубого поезда Ginga. Эта тема вызвала у автора ассоциацию с коктейлем «Транссибирский экспресс», характер которого захотелось перенести в структуру Negroni.\n\nОсновой напитка становится заготовка из облепихи, хвои, апельсиновой цедры, специй вкусового баланса и водки. Облепиха добавляет интенсивную ягодную кисло-сладкую ароматику, хвоя формирует смолистый лесной профиль, а апельсиновая цедра связывает композицию с цитрусовой природой классического биттера.\n\nКрасный вермут отвечает за винную сладость и пряность, а красный биттер сохраняет узнаваемую горькую конструкцию Negroni.\n\nПастила из облепихи становится съедобным продолжением напитка. Её можно попробовать между глотками, усиливая ягодный профиль и постепенно меняя восприятие горечи.\n\nОблепиховая часть: сушёная облепиха создаёт насыщенный ягодный профиль с выраженной фруктовой кислотностью и оттенками сухофруктов.\n\nХвойная часть: хвойное сырьё добавляет смолистую свежесть, лесные ароматы и высокую травянистость.\n\nЦитрусовая часть: апельсиновая цедра поддерживает красный биттер и добавляет аромат эфирных масел.\n\nВинная часть: красный вермут формирует сладость, специи и насыщенную ароматизированную винную основу.\n\nГорькая часть: красный биттер создаёт продолжительную аперитивную горечь и удерживает напиток в стилистике Negroni.\n\nКислотно-солевой баланс: лимонная и яблочная кислоты усиливают облепиховую свежесть, а соль делает вкус более объёмным и подчёркивает фруктовую сладость.',
