      intro:
        'Negroni Grecha — равнодольная интерпретация классического Negroni с джином, настоянным на обжаренной гречке. Campari и Martini Rosso сохраняют знакомую горько-сладкую структуру, а гречка добавляет тёплые злаковые, ореховые и слегка землистые оттенки.',
      story:
        'Negroni Grecha соединяет итальянскую коктейльную классику со вкусом, прочно связанным с русской гастрономической культурой.\n\nВ авторской концепции гречка становится примером продукта, который пришёл издалека, но настолько естественно вошёл в местную кухню, что начал восприниматься как домашний и родной. Похожий путь проходит и Negroni: коктейль сохраняет итальянскую структуру, но получает новый характер благодаря локальной вкусовой ассоциации.\n\nКлассическая формула остаётся неизменной: джин, Campari и Martini Rosso используются в равных пропорциях. Меняется только ароматическая основа — джин предварительно настаивается на обжаренных ядрах гречки.\n\nВо время обжаривания гречка приобретает выраженные злаковые, ореховые и тостовые оттенки. При настаивании они переходят в джин, смягчают его сухой можжевеловый профиль и добавляют напитку ощущение тепла и основательности.\n\nCampari отвечает за яркую цитрусово-травяную горечь, а Martini Rosso — за винную сладость, специи и пряные травы. Апельсиновая цедра поддерживает классическую ароматику Negroni, а окаёмка из приправы «Апельсиновый перец» добавляет дополнительный цитрусово-пряный акцент.\n\nВ результате получается узнаваемый Negroni с сухим, тёплым и слегка землистым гречневым послевкусием — итальянский аперитив с домашней русской интонацией.\n\nГречнево-ботаническая основа: джин на обжаренной гречке формирует сухой можжевеловый каркас с оттенками жареного зерна, орехов и тёплой корочки.\n\nГорькая часть: Campari создаёт интенсивную цитрусово-травяную горечь и продолжительное аперитивное послевкусие.\n\nВинная часть: Martini Rosso добавляет сладость, специи, травы и насыщенность красного ароматизированного вина.\n\nЦитрусово-пряный акцент: апельсиновая цедра усиливает эфирную ароматику, а приправа на краю бокала добавляет дополнительную пряность.\n\nОбщий профиль крепкий, выраженно горький и умеренно сладкий, с тостовыми гречневыми оттенками и сухим цитрусовым финалом.',
      image: '/images/recipes/Negroni Grecha.png',
