      story:
        '«Проходимец» начинается с русского джина — холодного, чистого и уверенного.\n\nBarrister B47 Bartender’s Edition формирует крепкий ботанический каркас. Следом раскрывается Carpano Antica Formula — насыщенный красный вермут с пряной сладостью и глубокой травяной ароматикой. В авторской истории это старый итальянский шёпот, в котором горечь хорошо знает цену сладости.\n\nCampari и трипл-сек добавляют движение и контраст: цитрусовая горечь сменяется мягкой апельсиновой сладостью, свет — тенью, прямота — обманом.\n\nВетивер и зизифора формируют самую холодную и загадочную часть композиции. Землистый, древесный ветивер напоминает влажную траву и корни под ногами, а зизифора добавляет прохладные травяные и пряные оттенки.\n\nФинальной деталью становится клубничный мармелад с апельсиновым ликёром. Он выглядит как обещание сладкого завершения, но продолжает цитрусовую горечь основного напитка.\n\nПо авторскому образу это последняя ложь, в которую гость с удовольствием поверит.\n\nДжиновая основа: Barrister B47 Bartender’s Edition создаёт сухой можжевеловый каркас и поддерживает высокую крепость напитка.\n\nВинно-пряная часть: Carpano Antica Formula добавляет сладость, ваниль, специи, тёмные травы и насыщенный винный объём.\n\nГорькая часть: Campari формирует выраженную цитрусово-травяную горечь и продолжительное аперитивное послевкусие.\n\nАпельсиновая часть: Joseph Cartron Triple Sec добавляет аромат апельсиновой цедры, мягкую сладость и связывает джин с Campari.\n\nЗемлисто-травяная часть: ветивер создаёт древесные, корневые и землистые оттенки. Зизифора усиливает прохладную травянистость и пряную ароматику.\n\nСъедобное сопровождение: клубнично-апельсиновый мармелад добавляет фруктовую сладость и меняет восприятие горечи между глотками.',
