      intro:
        'Крепкая дымная вариация на классический Negroni. Равные части джина, красного вермута и Campari дополняются торфяным виски Laphroaig, который добавляет йодистые, копчёные и древесные оттенки. Во вкусе сочетаются сладость вермута, аперитивная горечь и продолжительное дымно-травяное послевкусие.',
      story:
        'Авторская история коктейля в присланной заявке отсутствует.\n\nПо составу напиток строится вокруг классической равнодольной формулы Negroni: джин формирует сухую ботаническую основу, красный вермут отвечает за винную сладость и пряность, а Campari — за характерную цитрусово-травяную горечь.\n\nДополнительным компонентом становится Laphroaig — торфяной островной виски с ярким дымным характером. Небольшая порция виски заметно меняет привычную конструкцию: появляются оттенки костра, древесного угля, морской соли и копчёных трав.\n\nЕсли Laphroaig действительно наносится верхним слоем, его аромат будет особенно заметен в первых глотках. Затем дымный профиль постепенно соединится с вермутом и Campari, оставляя продолжительное горько-травяное послевкусие.\n\nАвтор описывает напиток коротко и прямо: «Крепко, сладко, с дымным травяным послевкусием».\n\nДжиновая основа: джин создаёт сухой можжевеловый каркас и поддерживает классическую архитектуру Negroni.\n\nВинная часть: красный вермут добавляет сладость, специи, травы и насыщенность ароматизированного вина.\n\nГорькая часть: Campari формирует яркую цитрусово-травяную горечь и продолжительное аперитивное послевкусие.\n\nДымная часть: Laphroaig добавляет торфяные, копчёные, йодистые и древесные оттенки.\n\nОбщий профиль крепкий, сладко-горький и насыщенный, с выраженным дымным ароматом и травяным завершением.',
      image: '/images/recipes/Fireplace.png',
