      intro:
        'Rye Bread Negroni — пряная интерпретация классического коктейля с женевером на обжаренных кориандре и тмине. Красный вермут и Campari сохраняют узнаваемый горько-сладкий профиль, а специи и ржаной сухарик создают ассоциацию с корочкой свежеиспечённого бородинского хлеба.',
      story:
        'Работая с концепцией джинового бара, Кирида Орсини решила обратиться к истокам категории и построить коктейль на женевере.\n\nВ авторской истории женевер становится связующим звеном между европейской традицией и локальными русскими вкусами. Его более плотный зерновой профиль дополняется кориандром и тмином — специями, которые ассоциируются с ароматом ржаного и бородинского хлеба.\n\nПеред настаиванием специи прогреваются на сухой сковороде и слегка разминаются. Термическая обработка делает их аромат теплее и выразительнее: проявляются цитрусовые оттенки кориандра, землистая пряность тмина и впечатление поджаренной хлебной корочки.\n\nКрасный вермут добавляет винную сладость, травы и специи. Campari сохраняет центральную аперитивную горечь и узнаваемый характер Negroni. Небольшое количество солевого компонента должно сделать вкус более собранным и подчеркнуть зерновые и пряные оттенки.\n\nРжаной сухарик завершает подачу и превращает хлебную ассоциацию в полноценную часть дегустации.\n\nВ результате классический Negroni сохраняет свой стиль, но получает тёплое хлебно-пряное послевкусие с кориандром, тмином и оттенками поджаренного зерна.\n\nЗерновая основа: женевер добавляет плотный зерновой характер и формирует более мягкий, солодовый профиль по сравнению с классической джиновой основой.\n\nХлебно-пряная часть: обжаренные кориандр и тмин создают цитрусовые, землистые и тёплые пряные оттенки, связанные с ароматом бородинского хлеба.\n\nВинная часть: красный вермут добавляет сладость, травы, специи и объём ароматизированного вина.\n\nГорькая часть: Campari формирует характерную цитрусово-травяную горечь и продолжительное аперитивное послевкусие.\n\nСолевой баланс: солевой компонент подчёркивает сладость вермута, смягчает спиртуозность и усиливает зерново-пряный профиль.\n\nГарнир: ржаной сухарик поддерживает главную вкусовую ассоциацию и добавляет хрустящую текстуру.',
      image: '/images/recipes/Rye Bread Negroni.png',
