      barDescription:
        'Денис Попков представляет «Энзони» как более свежую и фруктовую альтернативу классическому Negroni. Джин и Campari сохраняют знакомую ботаническую и горькую основу, а зелёный виноград, лимонный сок и сахарный сироп переводят напиток в формат сочного сауэра. Интенсивное взбивание делает коктейль прохладным, ярким и подходящим для гостей, которым нравится горечь аперитивов, но не хватает в классической формуле кислотности и свежих фруктов.',
