      intro:
        '«Энзони» — освежающий виноградный коктейль на джине и Campari. Зелёный виноград добавляет сочную фруктовость, лимонный сок — яркую кислотность, а сахарный сироп смягчает характерную горечь итальянского биттера. Получается насыщенный, но питкий напиток с можжевеловой основой и продолжительным цитрусово-виноградным послевкусием.',
      story:
        '«Энзони» показывает, как знакомую горько-сладкую структуру Negroni можно сделать свежее, ярче и легче по восприятию.\n\nВ предоставленной автором исторической справке появление коктейля связывается с нью-йоркским баром Milk & Honey и идеей переосмыслить сочетание джина с Campari. Вместо сладкого красного вермута в рецепте появляются свежий лимонный сок, сахарный сироп и зелёный виноград.\n\nТак коктейль уходит от плотной винно-травяной структуры Negroni в сторону сочного ягодно-цитрусового сауэра.\n\nДжин Hoppers сохраняет сухой ботанический каркас и добавляет можжевеловую пряность. Campari формирует узнаваемую апельсиново-травяную горечь. Свежий виноград отвечает за фруктовую мягкость и лёгкую терпкость кожицы, а лимонный сок делает вкус ярким и динамичным.\n\nСахарный сироп не только балансирует кислотность, но и подчёркивает естественную сладость винограда. После интенсивного взбивания коктейль приобретает прохладную сочность и более округлую текстуру.\n\nВ результате получается напиток для тех, кому нравится характер Negroni, но хочется больше свежести, кислотности и живого фруктового вкуса.\n\nДжиновая основа: джин Hoppers задаёт крепость, сухость и можжевелово-ботанический профиль.\n\nГорькая часть: Campari добавляет апельсиновую цедру, горькие травы, специи и продолжительное аперитивное послевкусие.\n\nВиноградная часть: раздавленный зелёный виноград создаёт сочную фруктовую сладость, свежий аромат, лёгкую терпкость кожицы и мягкий виноградный объём.\n\nЦитрусовая часть: свежий лимонный сок делает напиток ярким, освежающим и заметно более кислотным, чем классический Negroni.\n\nСладкий баланс: сахарный сироп связывает кислотность лимона с горечью Campari и округляет текстуру коктейля.',
