      barDescription:
        'Андрей Приб представляет #10 DAICHI HARADA как часть меню, созданного в формате картинной галереи вымышленных современных художников. В основе каждого изображения лежит реальный коктейль: его ингредиенты, цвет, аромат, вкусовой профиль и эмоциональное настроение переводятся в промпт для нейросети. Так напиток получает визуальное отражение, а гость может воспринимать одну идею одновременно через вкус и изображение.',
